package com.auth.service

import java.net.{InetAddress, URL}
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.util.concurrent.ConcurrentHashMap
import scala.util.{Try, Success, Failure}
import scala.collection.concurrent.TrieMap

// Circuit breaker states
sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(
  failureThreshold: Int = 5,
  resetTimeoutMs: Long = 30000,
  halfOpenMaxCalls: Int = 1
) {
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  private val halfOpenCalls = new AtomicInteger(0)
  @volatile private var state: CircuitState = Closed

  def getState: CircuitState = {
    if (state == Open && System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
      state = HalfOpen
      halfOpenCalls.set(0)
    }
    state
  }

  def recordSuccess(): Unit = {
    failureCount.set(0)
    state = Closed
  }

  def recordFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= failureThreshold) {
      state = Open
    }
  }

  def allowRequest(): Boolean = getState match {
    case Closed => true
    case Open => false
    case HalfOpen => halfOpenCalls.incrementAndGet() <= halfOpenMaxCalls
  }
}

case class AuthEndpoint(url: String, apiKey: String)

class PinnedDnsResolver {
  private val pinned = new ConcurrentHashMap[String, InetAddress]()

  def resolveAndPin(hostname: String): InetAddress = {
    val existing = pinned.get(hostname)
    if (existing != null) {
      existing
    } else {
      val resolved = InetAddress.getByName(hostname)
      pinned.putIfAbsent(hostname, resolved)
      pinned.get(hostname)
    }
  }

  def getPinned(hostname: String): Option[InetAddress] = Option(pinned.get(hostname))
}

class AuthenticationService(
  endpoints: List[AuthEndpoint],
  circuitBreaker: CircuitBreaker = new CircuitBreaker()
) {
  private val dnsResolver = new PinnedDnsResolver()
  private val tokenCache = TrieMap.empty[String, (String, Long)]
  private val TOKEN_TTL_MS = 300000L

  private def isInternalAddress(addr: InetAddress): Boolean = {
    addr.isLoopbackAddress ||
    addr.isSiteLocalAddress ||
    addr.isLinkLocalAddress
  }

  def validateEndpoint(endpoint: AuthEndpoint): Boolean = {
    Try {
      val url = new URL(endpoint.url)
      val hostname = url.getHost
      val resolved = dnsResolver.resolveAndPin(hostname)
      !isInternalAddress(resolved)
    }.getOrElse(false)
  }

  def authenticate(token: String, endpoint: AuthEndpoint): Either[String, String] = {
    // Check token cache first
    tokenCache.get(token) match {
      case Some((result, timestamp)) if System.currentTimeMillis() - timestamp < TOKEN_TTL_MS =>
        Right(result)
      case _ =>
        performAuthentication(token, endpoint)
    }
  }

  private def performAuthentication(token: String, endpoint: AuthEndpoint): Either[String, String] = {
    if (!circuitBreaker.allowRequest()) {
      return Left("Circuit breaker is open - service unavailable")
    }

    // Validate endpoint before making request
    if (!validateEndpoint(endpoint)) {
      circuitBreaker.recordFailure()
      return Left("Invalid endpoint - internal addresses not allowed")
    }

    // Use the pinned DNS resolution to prevent rebinding
    // Verify the connection-time address matches our pinned resolution
    Try {
      val url = new URL(endpoint.url)
      val hostname = url.getHost
      val pinnedAddr = dnsResolver.getPinned(hostname).getOrElse {
        throw new SecurityException("No pinned address for hostname")
      }

      // Re-verify the pinned address is still safe at connection time
      if (isInternalAddress(pinnedAddr)) {
        throw new SecurityException("Pinned address resolved to internal network")
      }

      // Connect using the pinned IP directly to prevent rebinding
      val port = if (url.getPort == -1) url.getDefaultPort else url.getPort
      val directUrl = new URL(url.getProtocol, pinnedAddr.getHostAddress, port, url.getFile)
      val connection = directUrl.openConnection()
      connection.setConnectTimeout(5000)
      connection.setReadTimeout(5000)
      connection.setRequestProperty("Host", hostname)
      connection.setRequestProperty("Authorization", s"Bearer $token")
      connection.setRequestProperty("X-API-Key", endpoint.apiKey)

      val response = scala.io.Source.fromInputStream(connection.getInputStream).mkString
      circuitBreaker.recordSuccess()
      tokenCache.put(token, (response, System.currentTimeMillis()))
      Right(response)
    } match {
      case Success(result) => result
      case Failure(ex) =>
        circuitBreaker.recordFailure()
        Left(s"Authentication failed: ${ex.getMessage}")
    }
  }

  def authenticateWithRetry(token: String, maxRetries: Int = 3): Either[String, String] = {
    val activeEndpoints = endpoints.filter(validateEndpoint)
    if (activeEndpoints.isEmpty) {
      return Left("No valid endpoints available")
    }

    var lastError: String = ""
    for {
      attempt <- 0 until maxRetries
      endpoint = activeEndpoints(attempt % activeEndpoints.size)
    } {
      authenticate(token, endpoint) match {
        case Right(result) => return Right(result)
        case Left(error) =>
          lastError = error
          // Do NOT invalidate DNS pins on failure - prevents rebinding
      }
    }
    Left(s"All retries exhausted: $lastError")
  }
}
